#!/usr/bin/env bash\nset -euo pipefail\n\n# Football-only in-GMT test for the task-specific MimicLite VLA checkpoint.\n\nSCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"\nISAACLAB_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"\n\nfind_latest_complete_model() {\n  local checkpoints_dir="$1"\n  local latest_step=-1 latest_model_path=""\n  local checkpoint_dir step candidate step_value\n  for checkpoint_dir in "${checkpoints_dir}"/*; do\n    [[ -d "${checkpoint_dir}" ]] || continue\n    step="$(basename "${checkpoint_dir}")"\n    [[ "${step}" =~ ^[0-9]+$ ]] || continue\n    candidate="${checkpoint_dir}/pretrained_model"\n    [[ -s "${candidate}/config.json" && -s "${candidate}/model.safetensors" ]] || continue\n    step_value=$((10#${step}))\n    if (( step_value > latest_step )); then\n      latest_step=${step_value}\n      latest_model_path="${candidate}"\n    fi\n  done\n  [[ -n "${latest_model_path}" ]] || {\n    echo "Error: no complete numeric football checkpoint under ${checkpoints_dir}" >&2\n    return 1\n  }\n  printf '%s' "${latest_model_path}"\n}\n\nFOOTBALL_CHECKPOINTS_DIR="${FOOTBALL_CHECKPOINTS_DIR:-/ai/Yichi/zikang/mimiclite_v3.1/0726/diffusion_HOI_football/checkpoints}"\nFOOTBALL_MODEL_PATH="${FOOTBALL_MODEL_PATH:-$(find_latest_complete_model "${FOOTBALL_CHECKPOINTS_DIR}")}"\nFOOTBALL_STEP="$(basename "$(dirname "${FOOTBALL_MODEL_PATH}")")"\n\n# MimicLite GMT backend / BeyondMimic actuator PD configuration.\nexport MIMIC_LITE_ROBOT_CFG=1\nexport VLA_MIMICLITE_YAW_CALIB_DEG=0.0\nexport MODEL_PATHS_CSV="${FOOTBALL_MODEL_PATH}"\nexport ENV_CONFIG_YAML="${FOOTBALL_ENV_CONFIG_YAML:-tasks/common_test_config/base_test/football_single_sonic_test.yaml}"\nexport NUM_WORKERS="${NUM_WORKERS:-2}"\nexport RESUME_LATEST="${RESUME_LATEST:-0}"\nexport CONDA_BASE="${CONDA_BASE:-/ai/Yichi/0_Systems/miniconda3}"\nexport CONDA_ENV_NAME="${CONDA_ENV_NAME:-unitree_sim_env}"\nexport AUTO_ACTIVATE_CONDA="${AUTO_ACTIVATE_CONDA:-1}"\n\nRESULTS_ROOT="${RESULTS_ROOT:-${ISAACLAB_ROOT}/script/eval_results_in_gmt_mimic_lite}"\nRUN_TS="${RUN_TS:-$(date +%Y%m%d_%H%M%S)}"\nexport RESULTS_TAG="${RESULTS_TAG:-in_gmt_mimic_lite_football_${FOOTBALL_STEP}}"\nexport RESULTS_DIR="${RESULTS_DIR:-${RESULTS_ROOT}/${RESULTS_TAG}_${RUN_TS}/football}"\n\necho "[mimiclite_in_gmt_football] model=${FOOTBALL_MODEL_PATH}"\necho "[mimiclite_in_gmt_football] gmt_backend=mimic_lite, MIMIC_LITE_ROBOT_CFG=${MIMIC_LITE_ROBOT_CFG}"\necho "[mimiclite_in_gmt_football] results=${RESULTS_DIR}"\n\nexec "${ISAACLAB_ROOT}/script/eval_scripts/mimic_lite/HOI_football_run_vla_eval_parallel.sh"\n